    var mc={}; H.mis.forEach(function(m){ m._i=info({hex:m.h,type:m.t,reg:m.r,flight:m.f}); if(m._i.cat==='otro'&&m.c&&CAT[m.c]) m._i.cat=m.c; mc[m._i.cat]=(mc[m._i.cat]||0)+1; });
