      document.getElementById('rd-mis').innerHTML=arr.slice(0,nshow).map(function(m){ var c=iso(m.h,m.r), zz=(m.z||[]).slice(0,3).map(cname).join(', ');
        return '<li><a href="#" data-mi="'+H.mis.indexOf(m)+'"><span class="i">'+svgIcon(m._i.cat,m.t,22,45)+'</span><span class="m"><b>'+esc(m.f||m.r||m.h.toUpperCase())+' <small style="color:var(--mu);font-weight:400;font-size:12.5px">· '+esc(m._i.name)+'</small></b><span>'+cflag(c)+' '+esc(cname(c))+(zz?' · '+T('sobre ','over ')+esc(zz):'')+'</span></span><span class="v"><b>'+hm(m.t1-m.t0)+'</b><small>'+dshort(m.t0)+' · '+nf(m.km)+' km</small></span></a></li>'; }).join('');
