function showMission(m){ var L=S.L, H=S.hist; if(!m||!S.map) return; var cur=m.tr.map(function(p){ return [m.t0+p[3],p[0],p[1],p[2]<0?-1:p[2]*100]; });
  S.trk={h:m.h,cur:cur,ss:[cur],all:cur}; S.heatOn=false; drawTrack(cur); if(S.hheat&&S.map.hasLayer(S.hheat)){ S.map.removeLayer(S.hheat); var hb=document.getElementById('rd-hon'); if(hb) hb.classList.remove('on'); }
  var i=m._i||info({hex:m.h,type:m.t,reg:m.r,flight:m.f}), c=iso(m.h,m.r), mx=0; cur.forEach(function(p){ if(p[3]>mx) mx=p[3]; });
  var sd=document.getElementById('rd-side'); var st={hex:m.h,flight:m.f,reg:m.r,type:m.t,_c:c};
  sd.innerHTML='<div class="rd-pan" id="rd-pan">'+headHTML(st,i)
   +'<div class="rd-sec">'+T('Misión','Mission')+'</div><div class="rd-trk"><div class="big">'+hm(m.t1-m.t0)+' <small>'+T('en el aire sin apagar el transpondedor','in the air without switching the transponder off')+'</small></div>'
   +'<div class="ln">'+T('Desde el ','From ')+'<b>'+dshort(m.t0)+' '+hhmm(m.t0)+'</b>'+T(' hasta el ',' to ')+'<b>'+dshort(m.t1)+' '+hhmm(m.t1)+'</b> <span style="font-size:11.5px">('+T('tu hora local','your local time')+')</span></div>'
   +'<div class="ln">'+T('Distancia ≈ ','Distance ≈ ')+'<b>'+nf(m.km)+' km</b> · '+T('altitud máx. ','max altitude ')+'<b>'+nf(mx)+' ft</b></div>'
   +((m.z||[]).length?'<div class="ln">'+T('Sobrevoló: ','Flew over: ')+(m.z||[]).map(function(k){ return cflag(k)+' '+esc(cname(k)); }).join(', ')+'</div>':'')
   +profile(cur)+'<div class="rd-btns"><button type="button" class="rd-btn" id="rd-tfit">'+T('Encuadrar','Fit to route')+'</button><button type="button" class="rd-btn" id="rd-mheat">'+T('Mapa de calor del vuelo','Flight heat map')+'</button><a class="rd-btn" href="#/radar?h='+m.h+'">'+T('¿Vuela ahora?','Flying now?')+'</a></div></div>'
   +fichaCard(i)+'<div class="rd-sec">'+T('Datos del avión','Aircraft data')+'</div>'+dlHTML(st,i)+'</div>';
  var x=document.getElementById('rd-close'); if(x) x.onclick=function(){ drawTrack(null); S.trk=null; if(S.hheat&&!S.map.hasLayer(S.hheat)){ S.hheat.addTo(S.map); var hb=document.getElementById('rd-hon'); if(hb) hb.classList.add('on'); } sd.innerHTML='<div class="rd-ph0"></div>'; };
  document.getElementById('rd-tfit').onclick=fitTrack; document.getElementById('rd-mheat').onclick=function(){ S.heatOn=!S.heatOn; this.classList.toggle('on',S.heatOn); drawTrack(cur); };
  fitTrack(); if(window.innerWidth<980){ var mp=document.getElementById('rd-map'); if(mp) mp.scrollIntoView({behavior:'smooth',block:'start'}); }
}
window.MAT_RADAR=function(app,ctx){ addCss(); stop(); S.ctx=ctx; var p=(ctx&&ctx.p)||[]; var tab=p[1]==='dias'?'dias':'live';
  if(S.map){ try{ S.map.remove(); }catch(e){} } S.map=null; S.mk={}; S.base=null; S.fitted=false; S.sel=null; S.trk=null; S.heat=null; S.hheat=null; TRL=null; S.data=S.data||null;
  if(ctx&&ctx.set) ctx.set(shell(tab),T('Radar aéreo','Air radar')); else app.innerHTML=shell(tab); S.root=app.querySelector('.rd');
  if(tab==='dias') dias(); else live();
};
